const body = $json;
const results = Array.isArray(body.results) ? body.results : [];
const answer = body.answer || body.sourcedAnswer || results[0]?.content || 'I could not find a confident answer.';
const sources = results.slice(0, 3).map((r) => ({ title: r.name || r.title || r.url, url: r.url, snippet: r.content || r.snippet || '' }));
return [{ json: { answer, sources } }];
